function NOBN_trk_PositionTransient_Set_DistanceToAlignment_Own(positionToolInfo)
	local od = positionToolInfo.Value
	return string.format("Distance to own alignment %.03f m", od)
end

function NOBN_trk_PositionTransient_Set_Distance_Ref(positionToolInfo)
	local rd = positionToolInfo.Value
	return string.format("Distance to reference alignment %.03f m", rd)
end

